import React, { useState, useEffect, useMemo } from 'react';

// Main component for the Jharkhand Academic Timetabling System (JATS)
const JharkhandAcademicSystem = () => {
  // --- STATE MANAGEMENT ---
  // Core state for UI
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentTab, setCurrentTab] = useState('dashboard');
  const [selectedStudentId, setSelectedStudentId] = useState(null);
  const [selectedClassForDateSheet, setSelectedClassForDateSheet] = useState(2); // Default to Grade 10-A

  // State for Gemini-powered features
  const [isSummaryLoading, setIsSummaryLoading] = useState(false);
  const [performanceSummary, setPerformanceSummary] = useState('');
  const [summaryError, setSummaryError] = useState('');
  const [isQuizLoading, setIsQuizLoading] = useState(false);
  const [quizTopic, setQuizTopic] = useState('');
  const [generatedQuiz, setGeneratedQuiz] = useState([]);
  const [userAnswers, setUserAnswers] = useState({});
  const [showQuizResults, setShowQuizResults] = useState(false);
  const [quizError, setQuizError] = useState('');
  const [isExplainLoading, setIsExplainLoading] = useState(false);
  const [quizExplanations, setQuizExplanations] = useState([]);
  const [isTimetableLoading, setIsTimetableLoading] = useState(false);
  const [timetableError, setTimetableError] = useState('');
  const [generatedTimetable, setGeneratedTimetable] = useState(null);
  const [timetableNotes, setTimetableNotes] = useState('Prioritize core subjects in morning; avoid back-to-back same subjects.');

  // --- MOCK DATABASE & DATA ---
  const teachers = [
    { teacher_id: 1, first_name: 'Priya', last_name: 'Sharma', subject_id: 1 }, // English
    { teacher_id: 2, first_name: 'Rajesh', last_name: 'Kumar', subject_id: 3 }, // Mathematics
    { teacher_id: 3, first_name: 'Sunita', last_name: 'Gupta', subject_id: 7 }, // Chemistry
    { teacher_id: 4, first_name: 'Amit', last_name: 'Singh', subject_id: 6 }, // Physics
    { teacher_id: 5, first_name: 'Deepa', last_name: 'Verma', subject_id: 4 }, // Science
  ];

  const classes = [
    { class_id: 1, class_name: 'Grade 9 - Section A' }, { class_id: 2, class_name: 'Grade 10 - Section A' },
    { class_id: 3, class_name: 'Grade 10 - Section B' }, { class_id: 4, class_name: 'Grade 11 - Science' },
    { class_id: 5, class_name: 'Grade 11 - Commerce' }, { class_id: 6, class_name: 'Grade 11 - Arts' },
    { class_id: 7, class_name: 'Grade 12 - Science' }, { class_id: 8, class_name: 'Grade 12 - Commerce' },
    { class_id: 9, class_name: 'Grade 12 - Arts' }
  ];

  const students = [
    { student_id: 151, first_name: 'Akshita', last_name: 'Guleria', class_id: 1 },
    { student_id: 1, first_name: 'Arjun', last_name: 'Reddy', class_id: 1 }, { student_id: 2, first_name: 'Nikhil', last_name: 'Desai', class_id: 1 },
    { student_id: 3, first_name: 'Rohan', last_name: 'Joshi', class_id: 2 }, { student_id: 4, first_name: 'Meera', last_name: 'Singh', class_id: 2 },
    ...Array.from({ length: 146 }, (_, i) => {
        const firstNames = ['Aisha', 'Vihaan', 'Ishaan', 'Siya', 'Kabir', 'Anika', 'Reyansh', 'Kiara', 'Vivaan', 'Myra', 'Advik', 'Riya', 'Arnav', 'Saanvi', 'Dhruv'];
        const lastNames = ['Gupta', 'Sharma', 'Verma', 'Kumar', 'Singh', 'Malhotra', 'Kapoor', 'Mehta', 'Patel', 'Shah', 'Agarwal', 'Jain', 'Mishra', 'Pandey'];
        return { student_id: 5 + i, first_name: firstNames[Math.floor(Math.random() * firstNames.length)], last_name: lastNames[Math.floor(Math.random() * lastNames.length)], class_id: (i % 9) + 1 };
    })
  ];

  const subjects = [ { subject_id: 1, subject_name: 'English' }, { subject_id: 2, subject_name: 'Hindi' }, { subject_id: 3, subject_name: 'Mathematics' }, { subject_id: 4, subject_name: 'Science' }, { subject_id: 5, subject_name: 'Social Science' }, { subject_id: 6, subject_name: 'Physics' }, { subject_id: 7, subject_name: 'Chemistry' }, { subject_id: 8, subject_name: 'Computer Science' }, { subject_id: 9, subject_name: 'Accountancy' }, { subject_id: 10, subject_name: 'Business Studies' }, { subject_id: 11, subject_name: 'History' }, { subject_id: 12, subject_name: 'Geography' }, { subject_id: 13, subject_name: 'Political Science' }, { subject_id: 14, subject_name: 'Economics' }, { subject_id: 15, subject_name: 'Fine Arts' } ];
  const exams = [ { exam_id: 1, exam_name: 'Class Test - 1' }, { exam_id: 2, exam_name: 'Half Yearly Examination' }, { exam_id: 3, exam_name: 'Annual Examination' } ];
  
  const baseResults = [
    // Existing Data
    { result_id: 1, student_id: 3, exam_id: 1, subject_id: 1, marks_obtained: 18.00, total_marks: 20.00 },
    { result_id: 2, student_id: 3, exam_id: 1, subject_id: 3, marks_obtained: 19.50, total_marks: 20.00 },
    { result_id: 3, student_id: 3, exam_id: 2, subject_id: 1, marks_obtained: 85.00, total_marks: 100.00 },
