                    <div className="flex items-center">
                      <div className="flex-shrink-0">
                        <div className="w-8 h-8 bg-blue-500 rounded-full flex items-center justify-center">
                          <span className="text-white text-sm font-bold">S</span>
                        </div>
                      </div>
                      <div className="ml-5 w-0 flex-1">
                        <dl>
                          <dt className="text-sm font-medium text-gray-500 truncate">Total Students</dt>
                          <dd className="text-lg font-medium text-gray-900">{students.length}</dd>
                        </dl>
                      </div>
                    </div>
                  </div>
                </div>
                <div className="bg-white overflow-hidden shadow rounded-lg">
                  <div className="p-5">
                    <div className="flex items-center">
                      <div className="flex-shrink-0">
                        <div className="w-8 h-8 bg-green-500 rounded-full flex items-center justify-center">
                          <span className="text-white text-sm font-bold">C</span>
                        </div>
                      </div>
                      <div className="ml-5 w-0 flex-1">
                        <dl>
                          <dt className="text-sm font-medium text-gray-500 truncate">Total Classes</dt>
                          <dd className="text-lg font-medium text-gray-900">{classes.length}</dd>
                        </dl>
                      </div>
                    </div>
                  </div>
                </div>
                <div className="bg-white overflow-hidden shadow rounded-lg">
                  <div className="p-5">
                    <div className="flex items-center">
                      <div className="flex-shrink-0">
                        <div className="w-8 h-8 bg-purple-500 rounded-full flex items-center justify-center">
                          <span className="text-white text-sm font-bold">T</span>
                        </div>
                      </div>
                      <div className="ml-5 w-0 flex-1">
                        <dl>
                          <dt className="text-sm font-medium text-gray-500 truncate">Total Teachers</dt>
                          <dd className="text-lg font-medium text-gray-900">{teachers.length}</dd>
                        </dl>
                      </div>
                    </div>
                  </div>
                </div>
                <div className="bg-white overflow-hidden shadow rounded-lg">
                  <div className="p-5">
                    <div className="flex items-center">
                      <div className="flex-shrink-0">
                        <div className="w-8 h-8 bg-orange-500 rounded-full flex items-center justify-center">
                          <span className="text-white text-sm font-bold">E</span>
                        </div>
                      </div>
                      <div className="ml-5 w-0 flex-1">
                        <dl>
                          <dt className="text-sm font-medium text-gray-500 truncate">Total Exams</dt>
                          <dd className="text-lg font-medium text-gray-900">{exams.length}</dd>
                        </dl>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}

          {currentTab === 'students' && (
            <div className="space-y-6">
              <h2 className="text-3xl font-bold text-gray-900">Students</h2>
              <div className="bg-white shadow overflow-hidden sm:rounded-md">
                <ul className="divide-y divide-gray-200">
                  {students.slice(0, 20).map(student => (
                    <li key={student.student_id}>
                      <div className="px-4 py-4 sm:px-6">
                        <div className="flex items-center justify-between">
                          <div className="flex items-center">
                            <div className="flex-shrink-0 h-10 w-10">
                              <div className="h-10 w-10 rounded-full bg-gray-300 flex items-center justify-center">
                                <span className="text-sm font-medium text-gray-700">
                                  {student.first_name[0]}{student.last_name[0]}
                                </span>
                              </div>
                            </div>
                            <div className="ml-4">
                              <div className="text-sm font-medium text-gray-900">
                                {student.first_name} {student.last_name}
                              </div>
                              <div className="text-sm text-gray-500">
                                {getClassName(student.class_id)}
                              </div>
                            </div>
                          </div>
                          <div className="text-sm text-gray-500">
                            ID: {student.student_id}
                          </div>
                        </div>
                      </div>
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          )}

          {currentTab === 'ai-tools' && (
            <div className="space-y-6">
              <h2 className="text-3xl font-bold text-gray-900">AI-Powered Tools</h2>
              
              {/* Performance Summary */}
              <div className="bg-white shadow rounded-lg p-6">
                <h3 className="text-lg font-medium text-gray-900 mb-4">Student Performance Summary</h3>
                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">Select Student</label>
                    <select
                      value={selectedStudentId || ''}
                      onChange={handleStudentSelect}
                      className="block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-blue-500 focus:border-blue-500"
                    >
                      <option value="">Choose a student...</option>
                      {students.filter(s => results.some(r => r.student_id === s.student_id))
                        .map(student => (
                          <option key={student.student_id} value={student.student_id}>
                            {student.first_name} {student.last_name} - {getClassName(student.class_id)}
                          </option>
                        ))}
                    </select>
                  </div>
                  <button
                    onClick={handleGenerateSummary}
                    disabled={!selectedStudentId || isSummaryLoading}
                    className="bg-blue-600 text-white px-4 py-2 rounded-md hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {isSummaryLoading ? 'Generating...' : 'Generate AI Summary'}
                  </button>
                  {summaryError && (
                    <div className="text-red-600 text-sm">{summaryError}</div>
                  )}
                  {performanceSummary && (
                    <div className="bg-blue-50 border border-blue-200 rounded-md p-4">
                      <h4 className="font-medium text-blue-900 mb-2">Performance Summary</h4>
                      <p className="text-blue-800">{performanceSummary}</p>
                    </div>
                  )}
                </div>
              </div>

              {/* Quiz Generator */}
              <div className="bg-white shadow rounded-lg p-6">
                <h3 className="text-lg font-medium text-gray-900 mb-4">AI Quiz Generator</h3>
                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">Topic</label>
                    <input
                      type="text"
                      value={quizTopic}
                      onChange={(e) => setQuizTopic(e.target.value)}
                      placeholder="Enter a topic (e.g., 'Indian History', 'Basic Mathematics')"
                      className="block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-blue-500 focus:border-blue-500"
                    />
                  </div>
                  <button
                    onClick={handleGenerateQuiz}
                    disabled={isQuizLoading}
                    className="bg-green-600 text-white px-4 py-2 rounded-md hover:bg-green-700 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {isQuizLoading ? 'Generating Quiz...' : 'Generate Quiz'}
                  </button>
                  {quizError && (
                    <div className="text-red-600 text-sm">{quizError}</div>
                  )}
                  {generatedQuiz.length > 0 && (
                    <div className="flex items-center gap-3">
                      <button onClick={handleCheckQuizAnswers} className="bg-emerald-600 text-white px-4 py-2 rounded-md hover:bg-emerald-700">Check Answers</button>
                      <button onClick={handleExplainQuiz} disabled={isExplainLoading} className="bg-emerald-50 text-emerald-700 border border-emerald-200 px-4 py-2 rounded-md disabled:opacity-50">
                        {isExplainLoading ? 'Explaining...' : 'Explain Answers'}
                      </button>
                    </div>
                  )}
                  {quizExplanations.length > 0 && (
                    <div className="bg-white border border-emerald-200 rounded-md p-4">
                      <h4 className="font-semibold text-emerald-800 mb-3">Explanations</h4>
                      <ul className="space-y-2">
                        {quizExplanations.map((ex, i) => (
                          <li key={i} className="text-sm"><span className="font-medium">Q{i+1}:</span> {ex.explanation} <span className={ex.correct ? 'text-green-700' : 'text-red-600'}>({ex.correct ? 'Correct' : 'Incorrect'})</span></li>
                        ))}
                      </ul>
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          {currentTab === 'leave' && (
            <div className="space-y-6">
              <h2 className="text-3xl font-bold text-gray-900">Leave Management</h2>
              <form onSubmit={handleAddLeave} className="bg-white shadow rounded-lg p-6 grid grid-cols-1 md:grid-cols-4 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Student</label>
                  <select value={newLeave.student_id} onChange={e=>setNewLeave({...newLeave, student_id: e.target.value})} className="w-full border border-gray-300 rounded-md px-3 py-2">
                    <option value="">Select...</option>
                    {students.slice(0, 50).map(s => (
                      <option key={s.student_id} value={s.student_id}>{s.first_name} {s.last_name} ({getClassName(s.class_id)})</option>
                    ))}
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Start Date</label>
                  <input type="date" value={newLeave.start_date} onChange={e=>setNewLeave({...newLeave, start_date: e.target.value})} className="w-full border border-gray-300 rounded-md px-3 py-2" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">End Date</label>
                  <input type="date" value={newLeave.end_date} onChange={e=>setNewLeave({...newLeave, end_date: e.target.value})} className="w-full border border-gray-300 rounded-md px-3 py-2" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Reason</label>
                  <input type="text" value={newLeave.reason} onChange={e=>setNewLeave({...newLeave, reason: e.target.value})} placeholder="Reason" className="w-full border border-gray-300 rounded-md px-3 py-2" />
                </div>
                <div className="md:col-span-4 flex justify-end">
                  <button type="submit" className="bg-emerald-600 text-white px-4 py-2 rounded-md hover:bg-emerald-700">Submit Request</button>
                </div>
              </form>
              <div className="bg-white shadow overflow-hidden sm:rounded-md">
                <ul className="divide-y divide-gray-200">
                  {leaveRequests.map(req => (
                    <li key={req.request_id} className="px-4 py-4 sm:px-6">
                      <div className="flex items-center justify-between">
                        <div>
                          <div className="text-sm font-medium text-gray-900">{getStudentFullName(req.student_id)}</div>
                          <div className="text-sm text-gray-500">{req.start_date} → {req.end_date} • {req.reason}</div>
                        </div>
                        <div className="flex items-center gap-2">
                          <span className={`px-2 py-1 rounded text-xs ${req.status==='Approved'?'bg-green-100 text-green-700':req.status==='Rejected'?'bg-red-100 text-red-700':'bg-amber-100 text-amber-700'}`}>{req.status}</span>
                          {req.status==='Pending' && (
                            <>
                              <button onClick={()=>handleLeaveRequest(req.request_id,'Approved')} className="px-3 py-1 bg-emerald-600 text-white rounded">Approve</button>
                              <button onClick={()=>handleLeaveRequest(req.request_id,'Rejected')} className="px-3 py-1 bg-red-600 text-white rounded">Reject</button>
                            </>
                          )}
                        </div>
                      </div>
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          )}
          
          {currentTab === 'datesheet' && (
            <div className="space-y-6">
              <h2 className="text-3xl font-bold text-gray-900">Date Sheet</h2>
              <div className="bg-white rounded-lg shadow p-4 flex items-center gap-4">
                <label className="text-sm text-gray-700">Class</label>
                <select value={selectedClassForDateSheet} onChange={e=>setSelectedClassForDateSheet(Number(e.target.value))} className="border border-gray-300 rounded px-3 py-2">
                  {classes.map(c => (
                    <option key={c.class_id} value={c.class_id}>{c.class_name}</option>
                  ))}
                </select>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-white rounded-lg shadow p-4">
                  <h3 className="font-semibold text-emerald-800 mb-3">Class Test - 1</h3>
                  <ul className="space-y-2">
                    {(dateSheetData[selectedClassForDateSheet]?.classTest1 || []).map((d, i) => (
                      <li key={i} className="flex items-center justify-between text-sm">
                        <span className="text-gray-800">{d.subject}</span>
                        <span className="text-gray-500">{d.date} • {d.time}</span>
                      </li>
                    ))}
                  </ul>
                </div>
                <div className="bg-white rounded-lg shadow p-4">
                  <h3 className="font-semibold text-emerald-800 mb-3">Term 1 Half Yearly</h3>
                  <ul className="space-y-2">
                    {(dateSheetData[selectedClassForDateSheet]?.halfYearly || []).map((d, i) => (
                      <li key={i} className="flex items-center justify-between text-sm">
                        <span className="text-gray-800">{d.subject}</span>
                        <span className="text-gray-500">{d.date} • {d.time}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>
            </div>
          )}

          {currentTab === 'calendar' && (
            <div className="space-y-6">
              <h2 className="text-3xl font-bold text-gray-900">Event Calendar</h2>
              <div className="bg-white rounded-lg shadow p-4">
                <ul className="divide-y divide-gray-200">
                  {eventData.sort((a,b)=>a.date.localeCompare(b.date)).map((ev, i) => (
                    <li key={i} className="py-3 flex items-center justify-between">
                      <div>
                        <div className="text-sm font-medium text-gray-900">{ev.name}</div>
                        <div className="text-xs text-gray-500">{ev.date}</div>
                      </div>
                      <span className={`text-xs px-2 py-1 rounded ${ev.color}`}>{ev.type}</span>
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          )}

          {currentTab === 'ai-timetable' && (
            <div className="space-y-6">
              <h2 className="text-3xl font-bold text-gray-900">AI Timetable Generator</h2>
              <div className="bg-white rounded-lg shadow p-4 grid grid-cols-1 md:grid-cols-3 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Class</label>
                  <select value={selectedClassForDateSheet} onChange={e=>setSelectedClassForDateSheet(Number(e.target.value))} className="w-full border border-gray-300 rounded px-3 py-2">
                    {classes.map(c => (
                      <option key={c.class_id} value={c.class_id}>{c.class_name}</option>
                    ))}
                  </select>
                </div>
                <div className="md:col-span-2">
                  <label className="block text-sm font-medium text-gray-700 mb-1">Constraints/Notes</label>
                  <input type="text" value={timetableNotes} onChange={e=>setTimetableNotes(e.target.value)} className="w-full border border-gray-300 rounded px-3 py-2" />
                </div>
                <div className="md:col-span-3 flex justify-end">
                  <button onClick={handleGenerateTimetable} disabled={isTimetableLoading} className="bg-emerald-600 text-white px-4 py-2 rounded-md hover:bg-emerald-700 disabled:opacity-50">{isTimetableLoading ? 'Generating...' : 'Generate Timetable'}</button>
                </div>
              </div>
              {timetableError && <div className="text-red-600 text-sm">{timetableError}</div>}
              {generatedTimetable && (
                <div className="bg-white rounded-lg shadow p-4 overflow-x-auto">
                  <table className="min-w-full">
                    <thead>
                      <tr>
                        <th className="text-left p-2">Day</th>
                        {Array.from({length:7}).map((_,i)=>(<th key={i} className="text-left p-2">P{i+1}</th>))}
                      </tr>
                    </thead>
                    <tbody>
                      {['Mon','Tue','Wed','Thu','Fri'].map(day => (
                        <tr key={day} className="border-t">
                          <td className="p-2 font-medium text-gray-700">{day}</td>
                          {(generatedTimetable[day]||[]).slice(0,7).map((p, idx) => (
                            <td key={idx} className="p-2 text-sm">
                              <div className="font-medium text-gray-900">{p.subject}</div>
                              <div className="text-gray-500">{p.teacher}</div>
                            </td>
                          ))}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          )}

          {/* Add other tab contents here */}
          {currentTab === 'results' && (
            <div className="space-y-6">
              <h2 className="text-3xl font-bold text-gray-900">Student Results</h2>
              <div className="bg-white shadow overflow-hidden sm:rounded-lg">
                <table className="min-w-full divide-y divide-gray-200">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Student
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Exam
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Subject
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Marks
                      </th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    {results.slice(0, 20).map(result => (
                      <tr key={result.result_id}>
                        <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                          {getStudentFullName(result.student_id)}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                          {getExamName(result.exam_id)}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                          {getSubjectName(result.subject_id)}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                          {result.marks_obtained}/{result.total_marks}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default JharkhandAcademicSystem;
